#include "../core/material_factory.h"
#include <iostream>
using namespace P4MapKit::Material;
int checks=0;
void Check(bool value,const char* text){++checks;if(!value)throw std::runtime_error(text);}
template<class F> void Refuses(F f,const char* category){++checks;try{f();}catch(const Refused& e){if(e.name==category)return;throw;}throw std::runtime_error("expected named factory refusal");}
int main(){try{SymbolicArena arena;const auto local=MaterialFactoryInputContract(arena,"FLocalVertexFactory");Check(local.Interpolants.size()==9,"local rows");const auto skin=MaterialFactoryInputContract(arena,"TGPUSkinMorphVertexFactoryDefault");Check(skin.Interpolants.size()==12,"skin rows");Check(same(skin.Interpolants.at("in_texcoord6")[1],source(arena,"TexCoord",6,1)),"skin independent UV6");Check(same(skin.Interpolants.at("in_texcoord2")[2],source(arena,"Interpolant","in_texcoord2",2)),"skin unknown Z stays named");const auto mesh=MaterialFactoryInputContract(arena,"FMeshParticleVertexFactory");Check(mesh.Particle&&mesh.Interpolants.size()==4,"mesh particle contract");Check(same(mesh.Interpolants.at("in_color0")[0],source(arena,"VertexColor",Value::null(),0))&&same(mesh.Interpolants.at("in_color1")[0],source(arena,"ParticleColor",Value::null(),0)),"particle and vertex colors independent");const auto beam=MaterialFactoryInputContract(arena,"FParticleBeamTrailVertexFactory");Check(!beam.Interpolants.count("in_particle_position"),"beam position is not guessed");BindingContext context;context.Varyings["in_texcoord6"]=23;ConfigureMaterialFactoryBinding(arena,context,"TGPUSkinVertexFactoryDefault");Binder binder(arena,context);auto leaf=arena.mk("IN",{"attrib",23,1});Check(same(binder.leaf(leaf),source(arena,"TexCoord",6,1)),"factory semantic wins over varying location");auto fallback=arena.mk("IN",{"attrib",4,0});Check(same(binder.leaf(fallback),source(arena,"Interpolant","interpolant 4",0)),"unknown attribute stays named");Check(MaterialFactoryName(0xdd651790dd308138ull)=="TGPUSkinMorphVertexFactoryDefault","exact source hash resolves morph factory");Refuses([&]{MaterialFactoryInputContract(arena,"FNiagaraMeshVertexFactory");},"material vertex factory inputs");Refuses([&]{MaterialFactoryName(1);},"material vertex factory inputs");Refuses([&]{ConfigureMaterialFactoryBinding(arena,context,"FLocalVertexFactory");},"material factory binding conflict");std::cout<<"native factory semantic checks="<<checks<<"\n";}catch(const std::exception& e){std::cerr<<e.what()<<"\n";return 1;}return 0;}
